return ['project-id-version'=>'Lingua Forge 2.1.0','report-msgid-bugs-to'=>'https://wordpress.org/support/plugin/lingua-forge','last-translator'=>'admin','language-team'=>'German','mime-version'=>'1.0','content-type'=>'text/plain; charset=UTF-8','content-transfer-encoding'=>'8bit','pot-creation-date'=>'2026-06-01T15:14:22+00:00','po-revision-date'=>'2026-06-03 15:04+0000','x-generator'=>'Loco https://localise.biz/','x-domain'=>'lingua-forge','language'=>'de_DE','plural-forms'=>'nplurals=2; plural=n != 1;','x-loco-version'=>'2.8.5; wp-7.0; php-8.3.31','messages'=>['"%1$s %2$s" saved.'=>'"%1$s %2$s" gespeichert.','"%1$s" created. %2$d template updated.'=>'"%1$s" erstellt. %2$d Vorlage aktualisiert.' . "\0" . '"%1$s" erstellt. %2$d Vorlagen aktualisiert.','"%s" created.'=>'"%s" erstellt.','%d language not yet linked'=>'%d Sprache noch nicht verknüpft' . "\0" . '%d Sprachen noch nicht verknüpft','%d link updated.'=>'%d Link aktualisiert.' . "\0" . '%d Links aktualisiert.','%d locale pack installed.'=>'%d Lokalisierungspaket installiert.' . "\0" . '%d Lokalisierungspakete installiert.','%d navigation reference updated.'=>'%d Navigationsreferenz aktualisiert.' . "\0" . '%d Navigationsreferenzen aktualisiert.','%d part reference updated.'=>'%d Teil-Referenz aktualisiert.' . "\0" . '%d Teil-Referenzen aktualisiert.','%s Archive'=>'%s Archiv','(avg %.1f hits/block)'=>'(ø %.1f Treffer/Block)','(avg %.1f hits/entry)'=>'(Durchschnitt %.1f Treffer/Eintrag)','(disabled)'=>'deaktiviert','({skipped} had no replaceable links — re-scan to investigate)'=>'({skipped} hatten keine ersetzbaren Links — erneut scannen, um zu untersuchen)','.txt file(s) in the directory'=>'.txt-Datei(en) im Verzeichnis','<strong>Lingua Forge:</strong> %1$d localized template(s) from the &#8220;%2$s&#8221; theme are preserved in the database but are currently inactive. They will become active again if you reactivate that theme. To carry your translations to the new theme, regenerate them via <strong>Settings → Lingua Forge → Router → FSE scaffold</strong>.'=>'<strong>Lingua Forge:</strong> %1$d lokalisierte Vorlage(n) aus dem &#8220;%2$s&#8221;-Theme sind in der Datenbank erhalten, sind aber momentan inaktiv. Sie werden wieder aktiv, wenn du dieses Theme erneut aktivierst. Um deine Übersetzungen auf das neue Theme zu übertragen, generiere sie erneut über <strong>Einstellungen → Lingua Forge → Router → FSE-Scaffold</strong>.','<strong>{n}</strong> auto-fixable link(s)'=>'<strong>{n}</strong> automatisch reparierbare Link(s)','<strong>{n}</strong> link(s) needing manual review'=>'<strong>{n}</strong> Link(s) zur manuellen Überprüfung','<strong>{n}</strong> stale path(s)'=>'<strong>{n}</strong> veralteter Pfad(e)','<strong>{n}</strong> template issue(s)'=>'<strong>{n}</strong> Template-Problem(e)','Accepts compiled .mo files only. Filename must follow the pattern {textdomain}-{locale}.mo. Uploading a file with the same name as an existing one will replace it.'=>'Akzeptiert nur kompilierte .mo-Dateien. Der Dateiname muss dem Muster {textdomain}-{locale}.mo folgen. Das Hochladen einer Datei mit demselben Namen wie eine bestehende ersetzt sie.','Action'=>'Aktion','Actions'=>'Aktionen','active'=>'aktiv','Active Languages'=>'Aktive Sprachen','Active languages: add each language you want to support. Each language gets a URL prefix or subdomain and an hreflang tag in the page &lt;head&gt;.'=>'Aktive Sprachen: Füge jede Sprache hinzu, die du unterstützen möchtest. Jede Sprache erhält ein URL-Präfix oder eine Subdomain und ein hreflang-Tag im &lt;head&gt; der Seite.','Active Provider'=>'Aktueller Anbieter','Add entry'=>'Eintrag hinzufügen','Add instructions to improve the draft — e.g. make it shorter, add a conclusion section, use a more formal register, include an FAQ block…'=>'Anweisungen hinzufügen, um den Entwurf zu verbessern — z.B. kürzer machen, einen Abschlussabschnitt hinzufügen, einen formelleren Stil verwenden, eine FAQ-Block einfügen…','Add instructions to improve the draft — e.g. make it shorter, add a conclusion section, use a more formal register…'=>'Füge Anweisungen hinzu, um den Entwurf zu verbessern — z.B. kürzer machen, einen Abschlussabschnitt hinzufügen, einen formelleren Stil verwenden…','Add new entry'=>'Neuen Eintrag hinzufügen','Add one term per row. Both the source term and the target rendering are required. The language pair determines which translation jobs the constraint applies to.'=>'Füge einen Begriff pro Zeile hinzu. Sowohl der Quellbegriff als auch die Zielübersetzung sind erforderlich. Das Sprachpaar bestimmt, für welche Übersetzungsaufträge die Einschränkung gilt.','Adds a link to the home page so visitors can browse in their language.'=>'Fügt einen Link zur Startseite hinzu, damit Besucher in ihrer Sprache browsen können.','Administrators only (manage_options)'=>'Nur Administratoren (manage_options)','After changing the primary language, flush permalinks (section below) for the URL routing to update.'=>'Nach Änderung der primären Sprache die Permalinks (Abschnitt unten) aktualisieren, damit die URL-Routing-Änderungen wirksam werden.','After changing URL structure settings (path prefix ↔ subdomain), always visit Settings → Permalinks and click Save Changes to flush the rewrite rules.'=>'Nach Änderungen an den URL-Struktur-Einstellungen (Pfadpräfix ↔ Subdomain) besuche immer Einstellungen → Permalinks und klicke auf Änderungen speichern, um die Umschreibregeln zu aktualisieren.','AI Behaviour Preset'=>'KI-Verhaltensvorgabe','AI cache cleared. %d entry was removed.'=>'KI-Cache gelöscht. %d Eintrag wurde entfernt.' . "\0" . 'KI-Cache gelöscht. %d Einträge wurden entfernt.','AI Cache: lists cached AI responses with hit counts. Clear the whole cache or a single post\'s entries. Use "Clear" before testing a translation change — cached results are returned even when you change the AI preset or model until the cache entry is evicted.'=>'KI-Cache: listet zwischengespeicherte KI-Antworten mit Trefferzahlen auf. Leere den gesamten Cache oder die Einträge eines einzelnen Beitrags. Verwende "Leeren" vor einem Test einer Übersetzungsänderung — zwischengespeicherte Ergebnisse werden zurückgegeben, auch wenn du das KI-Voreinstellung oder Modell änderst, bis der Cache-Eintrag entfernt wird.','AI features are optional. Language routing, hreflang, the language switcher, and the translation group system all work without a provider configured.'=>'KI-Funktionen sind optional. Sprachrouting, hreflang, der Sprachumschalter und das Übersetzungsgruppensystem funktionieren alle ohne einen konfigurierten Anbieter.','AI Limits & Security'=>'KI-Grenzen & Sicherheit','AI provider returned an empty response.'=>'KI-Anbieter hat eine leere Antwort zurückgegeben.','AI Usage'=>'KI-Nutzung','Aim for 120–160 characters. Leave empty to use the excerpt fallback.'=>'Strebe 120–160 Zeichen an. Leer lassen, um den Auszug-Fallback zu verwenden.','All time'=>'Alle Zeiten','Allow editors to lock individual blocks'=>'Erlaube Redakteuren, einzelne Blöcke zu sperren','Allow Gutenberg template-editing mode on post screens'=>'Erlaube Gutenberg-Vorlagenbearbeitungsmodus auf Beitragsseiten','Also delete language assignments, translation relationships, meta descriptions, glossary, and Translation Memory when the plugin is uninstalled'=>'Auch Sprachzuweisungen, Übersetzungsbeziehungen, Meta-Beschreibungen, Glossar und Übersetzungsspeicher löschen, wenn das Plugin deinstalliert wird.','Also generate meta description'=>'Meta-Beschreibung ebenfalls generieren','Alternative (server-side):'=>'Alternativ (Server-seitig):','An unknown error occurred.'=>'Ein unbekannter Fehler ist aufgetreten.','and'=>'und','Anthropic (Claude)'=>'Anthropic (Claude)','any'=>'beliebig','API calls saved by cache'=>'API-Aufrufe, die durch den Cache gespeichert wurden','API Key'=>'API-Schlüssel','API Keys'=>'API-Schlüssel','API Keys Tab'=>'API-Schlüssel-Tab','API Response Cache'=>'API-Antwort-Cache','Applied ✓'=>'Angewandt ✓','Apply failed — please try again.'=>'Anwendung fehlgeschlagen — bitte versuche es erneut.','Apply to Block'=>'Auf Block anwenden','Apply to Editor'=>'Auf Editor anwenden','Apply to Footnote'=>'Auf Fußnote anwenden','Apply to Meta Description'=>'Auf Meta-Beschreibung anwenden','Apply translation'=>'Übersetzung anwenden','Applying…'=>'Wird angewendet…','Approximate size'=>'Ungefähre Größe','Archive'=>'Archiv','Archive: %s'=>'Archiv: %s','Authors and above (edit_published_posts)'=>'Autoren und höher (edit_published_posts)','Behavior'=>'Verhalten','Behavior: choose the AI preset (Literal, Balanced, Creative), add site-wide custom prompt instructions, enable or disable automatic post-save translation, and configure the Translation Memory.'=>'Verhalten: Wähle die KI-Voreinstellung (Wörtlich, Ausgewogen, Kreativ), füge siteweite benutzerdefinierte Anweisungen hinzu, aktiviere oder deaktiviere die automatische Übersetzung nach dem Speichern des Beitrags und konfiguriere die Übersetzungsspeicher.','Block Content'=>'Blockinhalt','block descriptionRenders a polite notice when the current page is being shown in its source language because no translation exists for the visitor\'s language. Driven by the Lingua Forge router\'s LINGUAFORGE_LANG_FALLBACK_ACTIVE signal — emits nothing when a translation exists for the request locale.'=>'Zeigt eine höfliche Mitteilung, wenn die aktuelle Seite in ihrer Originalsprache angezeigt wird, weil keine Übersetzung für die Sprache des Besuchers vorhanden ist. Gesteuert durch das LINGUAFORGE_LANG_FALLBACK_ACTIVE Signal des Lingua Forge Routers — gibt nichts aus, wenn eine Übersetzung für die Anfrage-Sprache existiert.','Block Editor'=>'Block-Editor','block keywordfallback'=>'Fallback','block keywordi18n'=>'i18n','block keywordlanguage'=>'Sprache','block keywordlinguaforge'=>'linguaforge','block keywordtranslation'=>'Übersetzung','Block locking'=>'Block-Sperre','Block patterns registered for custom post types. Use the Translate button to produce a language variant. The translated content is saved here and can be copied into any CPT post from the block editor Pattern inserter or used as a starting point for a Synced Pattern (Reusable Block).'=>'Blockmuster, die für benutzerdefinierte Beitragstypen registriert sind. Verwende die Übersetzen-Schaltfläche, um eine Sprachvariante zu erstellen. Der übersetzte Inhalt wird hier gespeichert und kann vom Block-Editor Pattern-Inserter in jeden CPT-Beitrag kopiert oder als Ausgangspunkt für ein synchronisiertes Muster (Wiederverwendeter Block) verwendet werden.','block titleMissing Translation Notice'=>'Hinweis bei fehlender Übersetzung','Block translation reuses'=>'Block-Übersetzungs-Wiederverwendung','Block-level translation cache shared across posts. When enabled, identical blocks (same markup, language pair, and glossary) are served from memory instead of calling the AI again. Configure in Settings → Behavior.'=>'Blockübersetzungs-Cache, der über Beiträge hinweg geteilt wird. Wenn aktiviert, werden identische Blöcke (gleiche Markup, Sprachpaar und Glossar) aus dem Speicher bedient, anstatt die KI erneut aufzurufen. Konfiguriere in Einstellungen → Verhalten.','Browser language redirect'=>'Browser-Sprachumleitung','Built-in preset instructions:'=>'Integrierte Voreinstellungen: ','Bulletize (•-prefixed)'=>'Aufzählung (•-Präfix)','Cache translated equivalents at the block level so reusable content (shared footers, sidebars, accordions, boilerplate-heavy legal sections) does not pay an API call every time. When enabled, the translation flow parses each post into blocks, looks each block up in the cache, and sends only uncached blocks to the AI in a single batched request. Glossary edits and Compliance preset changes automatically invalidate affected cached translations. View statistics and clear the cache under Maintenance.'=>'Übersetze die Äquivalente auf Blockebene zwischen, damit wiederverwendbare Inhalte (gemeinsame Fußzeilen, Seitenleisten, Akkordeons, rechtlich schwere Standardabschnitte) bei jedem API-Aufruf nicht erneut bezahlt werden müssen. Wenn aktiviert, zerlegt der Übersetzungsfluss jeden Beitrag in Blöcke, sucht jeden Block im Cache und sendet nur nicht gecachte Blöcke in einer einzigen Batch-Anfrage an die KI. Glossar-Änderungen und Änderungen an der Compliance-Voreinstellung invalidieren automatisch betroffene zwischengespeicherte Übersetzungen. Statistiken anzeigen und Cache unter Wartung löschen.','cached'=>'zwischengespeichert','Cached API responses'=>'Zwischengespeicherte API-Antworten','Cached block translations'=>'Zwischengespeicherte Blockübersetzungen','Cancel'=>'Abbrechen','Cannot determine target language from slug.'=>'Ziel-Sprache kann aus dem Slug nicht bestimmt werden.','Cap how much AI usage the site can generate and restrict which user roles may trigger paid AI calls. Sits on top of the per-user rate limit (30 requests / minute, hardcoded) that already protects against single-user runaway loops.'=>'Begrenze die Nutzung der KI auf der Seite und beschränke, welche Benutzerrollen kostenpflichtige KI-Anfragen auslösen dürfen. Überlagert die pro-Benutzer-Grenze (30 Anfragen / Minute, fest codiert), die bereits vor unkontrollierten Schleifen schützt.','chars'=>'Zeichen','Chunk translated'=>'Abschnitt übersetzt','Chunk translated to:'=>'Abschnitt übersetzt zu:','Clear'=>'Löschen','Clear All'=>'Alles löschen','Clear all cached AI results? Future requests will trigger fresh API calls until the cache rebuilds.'=>'Alle zwischengespeicherten KI-Ergebnisse löschen? Zukünftige Anfragen lösen neue API-Aufrufe aus, bis der Cache neu aufgebaut ist.','Clear API Response Cache'=>'API-Antwort-Cache leeren','Clear Debug Files'=>'Debug-Dateien löschen','Clear hints'=>'Hinweise löschen','Clear input'=>'Eingabe löschen','Clear the entire Translation Memory? Future translations will rebuild the cache as they run.'=>'Gesamten Übersetzungsspeicher löschen? Zukünftige Übersetzungen bauen den Cache beim Ausführen neu auf.','Clear Translation Memory'=>'Übersetzungsspeicher löschen','Close'=>'Schließen','Close language panel'=>'Sprachpanel schließen','Close popover'=>'Popover schließen','Compliance Preset'=>'Compliance-Voreinstellung','Content generated'=>'Inhalt erstellt','Content Generator'=>'Content-Generator','Content ready'=>'Inhalt fertig','Contributors and above — default (edit_posts)'=>'Mitwirkende und höher – Standard (edit_posts)','Control how much content is sent to the AI and how large the response can be. Leave a field blank to use the built-in default (shown as placeholder). Raise these values if large pages are being cut off; lower them to reduce API costs.'=>'Steuere, wie viel Inhalt an die KI gesendet wird und wie groß die Antwort sein darf. Lass ein Feld leer, um den integrierten Standard zu verwenden (als Platzhalter angezeigt). Erhöhe diese Werte, wenn große Seiten abgeschnitten werden; senke sie, um API-Kosten zu reduzieren.','Controls the token budget and input limits for the AI Content Generator feature. Leave fields blank to use the built-in defaults.'=>'Steuert das Token-Budget und die Eingabebegrenzungen für die Funktion des KI-Content-Generators. Lasse die Felder leer, um die integrierten Standardwerte zu verwenden.','Controls what happens when an administrator deletes the plugin from Plugins → Installed Plugins → Delete. Plugin settings and AI caches are always removed. Language assignments and translation relationships are kept by default so an accidental uninstall or a reinstall can pick up where it left off.'=>'Steuert, was passiert, wenn ein Administrator das Plugin in Plugins → Installierte Plugins → Löschen entfernt. Plugin-Einstellungen und AI-Caches werden immer entfernt. Sprachzuweisungen und Übersetzungsbeziehungen bleiben standardmäßig erhalten, damit eine versehentliche Deinstallation oder Neuinstallation dort anknüpfen kann, wo sie aufgehört hat.','Conversational'=>'Gesprächig','Copied ✓'=>'Kopiert ✓','Copy'=>'Kopieren','Copy markup'=>'Markup kopieren','Copy the result and paste it wherever needed (e.g. directly into the footnote field).'=>'Kopiere das Ergebnis und füge es bei Bedarf ein (z.B. direkt in das Fußnotefeld).','Copy to safe storage'=>'In sicheren Speicher kopieren','Could not add entry: source term and target term are required.'=>'Eintrag konnte nicht hinzugefügt werden: Quell- und Zielbegriff sind erforderlich.','Could not copy the file. Check that the uploads folder is writable.'=>'Datei konnte nicht kopiert werden. Überprüfe, ob der Upload-Ordner beschreibbar ist.','Could not instantiate the provider.'=>'Der Anbieter konnte nicht instanziiert werden.','Could not save the file. Check that the uploads folder is writable.'=>'Datei konnte nicht gespeichert werden. Überprüfe, ob der Upload-Ordner beschreibbar ist.','Could not save the glossary entry.'=>'Das Glossareintrag konnte nicht gespeichert werden.','CPT Block Patterns'=>'CPT-Blockmuster','Create'=>'Erstellen','Create missing'=>'Erstellen, was fehlt','Creating translations for post type "%s" requires an active integration. Please ensure the required integration is installed and active.'=>'Das Erstellen von Übersetzungen für den Beitragstyp "%s" erfordert eine aktive Integration. Bitte stelle sicher, dass die erforderliche Integration installiert und aktiviert ist.','Creating…'=>'Wird erstellt…','Creative / Marketing'=>'Kreativ / Marketing','Creative / Marketing instructions'=>'Kreative / Marketing-Anweisungen','Current content (will be overwritten)'=>'Aktueller Inhalt (wird überschrieben)','Current title'=>'Aktueller Titel','Current: {current}'=>'Aktuell: {current}','Currently inherited from the %s constant. Selecting a value here will override it.'=>'Derzeit geerbt vom %s-Konstanten. Die Auswahl eines Werts hier überschreibt ihn.','Currently skipped for posts that use block-comment attribute placeholders (wp:details summary fields, etc.) — they fall through to the existing single-call translation path.'=>'Derzeit übersprungen für Beiträge, die Block-Kommentar-Attribut-Platzhalter verwenden (wp:details Zusammenfassungsfelder usw.) — sie fallen auf den bestehenden Einzel-Aufruf-Übersetzungsweg zurück.','Currently:'=>'Derzeit:','Custom'=>'Benutzerdefiniert','Daily AI quota reached (%1$d requests). Resets at %2$s UTC.'=>'Tägliches KI-Kontingent erreicht (%1$d Anfragen). Setzt um %2$s UTC zurück.','Daily request limit'=>'Tägliches Anfrage-Limit','Debug Files'=>'Debug-Dateien','Debug files cleared. %d file was removed.'=>'Debug-Datei gelöscht. %d Datei wurde entfernt.' . "\0" . 'Debug-Dateien gelöscht. %d Dateien wurden entfernt.','Debug logging'=>'Debug-Logging','Debug logging disabled.'=>'Debug-Logging deaktiviert.','Debug logging enabled.'=>'Debug-Logging aktiviert.','Debug: enable the debug log to capture AI prompts and API responses to a local file. Disable after troubleshooting — debug mode writes a file on every AI request.'=>'Debug: Aktiviere das Debug-Protokoll, um KI-Anfragen und API-Antworten in eine lokale Datei zu erfassen. Nach der Fehlerbehebung deaktivieren — der Debug-Modus schreibt bei jeder KI-Anfrage eine Datei.','Delete'=>'Löschen','Delete all .txt files in the debug directory? The directory itself will remain so future debug writes still land cleanly.'=>'Alle .txt-Dateien im Debug-Verzeichnis löschen? Das Verzeichnis selbst bleibt erhalten, damit zukünftige Debug-Schreibvorgänge weiterhin sauber landen.','Delete all files for this override (both .mo and .po)?'=>'Alle Dateien für diese Überschreibung löschen (sowohl .mo- als auch .po-Dateien)?','Delete content data on uninstall'=>'Inhalt bei Deinstallation löschen','Delete this glossary entry?'=>'Diesen Glossareintrag löschen?','Describe what to write — topic, key points, structure…'=>'Beschreibe, was geschrieben werden soll — Thema, Schlüsselpunkte, Struktur…','Directory'=>'Verzeichnis','Disable during prompt tuning or when you need every request to reach the AI provider. Disabling does not delete cached entries — re-enabling restores them. Increasing API spend immediately on busy sites is expected when disabled.'=>'Deaktiviere während der Feinabstimmung der Eingabeaufforderung oder wenn du jede Anfrage an den KI-Anbieter senden möchtest. Das Deaktivieren löscht keine zwischengespeicherten Einträge — das Reaktivieren stellt sie wieder her. Eine sofortige Erhöhung der API-Ausgaben auf stark frequentierten Seiten wird beim Deaktivieren erwartet.','Display'=>'Anzeige','Displays the Lingua Forge language switcher.'=>'Zeigt den Lingua Forge Sprachumschalter an.','Documentation'=>'Dokumentation','Done'=>'Fertig','Done — {done} of {total} post(s) fixed.'=>'Fertig — {done} von {total} Beiträgen repariert.','Down'=>'Nach unten','Download and install a WordPress core language pack directly from WordPress.org. Once installed, the locale becomes available for URL routing and the AI translation workflow. The list of available languages is fetched on demand — click the button below to load it.'=>'Lade und installiere ein WordPress-Kern-Lokalisierungspaket direkt von WordPress.org. Nach der Installation steht die Lokalisierung für URL-Routing und den KI-Übersetzungsworkflow zur Verfügung. Die Liste der verfügbaren Sprachen wird bei Bedarf abgerufen — klicke auf die Schaltfläche unten, um sie zu laden.','Dropdown direction'=>'Dropdown-Richtung','Editors and above (edit_others_posts)'=>'Redakteure und höher (edit_others_posts)','Enable API response caching'=>'API-Antwort-Cache aktivieren','Enable block-level translation cache reuse across posts'=>'Blockebenen-Übersetzungscache-Wiederverwendung über Beiträge hinweg aktivieren','Enter your API key for at least one AI provider. Keys are encrypted at rest using AES-256-GCM with a site-specific secret (LINGUAFORGE_SECRET). Do not share database exports without rotating the secret first.'=>'Gib deinen API-Schlüssel für mindestens einen KI-Anbieter ein. Schlüssel sind bei Ruhe verschlüsselt mit AES-256-GCM unter Verwendung eines sitzplatzabhängigen Geheimnisses (LINGUAFORGE_SECRET). Teile keine Datenbank-Exporte ohne vorheriges Rotieren des Geheimnisses.','environment variable'=>'Umweltvariable','Error'=>'Fehler','Expand'=>'Erweitern','Expected: {expected}'=>'Erwartet: {expected}','Extra guidance — tone, style, constraints, target audience…'=>'Zusätzliche Hinweise — Ton, Stil, Einschränkungen, Zielgruppe…','Extra guidance — tone, style, constraints…'=>'Zusätzliche Hinweise — Ton, Stil, Einschränkungen…','Failed. Please try again.'=>'Fehlgeschlagen. Bitte versuche es erneut.','Feature'=>'Funktion','Features are grouped into two tiers. Enter the exact model identifier for each tier and provider. Leave a field blank to use the built-in default (shown as placeholder). Only the active provider\'s models are called at runtime — configure the others in advance if you plan to switch.'=>'Funktionen sind in zwei Ebenen gruppiert. Gib die genaue Modellkennung für jede Ebene und jeden Anbieter ein. Lasse ein Feld leer, um den integrierten Standard zu verwenden (als Platzhalter angezeigt). Nur die aktiven Anbieter-Modelle werden zur Laufzeit aufgerufen — konfiguriere die anderen im Voraus, wenn du planst zu wechseln.','File copied to safe storage successfully.'=>'Datei erfolgreich in sicheren Speicher kopiert.','Files'=>'Dateien','Files land in the directory below. Useful for diagnosing translation issues — turn off once you have what you need so the files do not accumulate. You can also force this from wp-config.php with `define( \'LINGUAFORGE_AI_DEBUG\', true );` which overrides the toggle.'=>'Dateien landen im unten stehenden Verzeichnis. Nützlich zur Diagnose von Übersetzungsproblemen — schalte es aus, sobald du hast, was du brauchst, damit die Dateien sich nicht anhäufen. Du kannst dies auch in wp-config.php erzwingen mit `define( \'LINGUAFORGE_AI_DEBUG\', true );`, was den Schalter überschreibt.','Filter'=>'Filter','Filter with linguaforge_debug_dir to redirect debug output to a non-public location.'=>'Mit linguaforge_debug_dir filtern, um Debug-Ausgaben an einen nicht-öffentlichen Ort umzuleiten.','Fix'=>'Reparieren','Fix All'=>'Alle reparieren','Fix all links'=>'Alle Links reparieren','Fix all parts'=>'Alle Teile reparieren','Fix Links'=>'Links reparieren','Fix Nav'=>'Navigation reparieren','Fix Parts'=>'Teile reparieren','Fix Template'=>'Template reparieren','Fixing {n} / {total}…'=>'Repariere {n} / {total}…','Fixing…'=>'Wird repariert…','Flush Permalink Rules'=>'Permalink-Regeln leeren','Flush Permalinks'=>'Permalinks leeren','Footnote Content'=>'Fußnoteninhalte','footnote(s) translated — applied together with content.'=>'Fußnoten übersetzt — zusammen mit dem Inhalt angewendet.','Footnotes'=>'Fußnoten','Footnotes payload (advanced)'=>'Fußnoten-Payload (fortgeschritten)','Forbidden'=>'Verboten','Forced OFF by the LINGUAFORGE_AI_DEBUG constant in wp-config.php. Remove that line to control this toggle from here.'=>'Erzwungen AUS durch die Konstante LINGUAFORGE_AI_DEBUG in wp-config.php. Entferne diese Zeile, um diesen Schalter von hier aus zu steuern.','Forced ON by the LINGUAFORGE_AI_DEBUG constant in wp-config.php. Remove that line to control this toggle from here.'=>'Erzwungen EIN durch die Konstante LINGUAFORGE_AI_DEBUG in wp-config.php. Entferne diese Zeile, um diesen Schalter von hier aus zu steuern.','Found {parts} across <strong>{total}</strong> of <strong>{scanned}</strong> scanned post(s) for <strong>{lang}</strong>.'=>'Gefunden {parts} in <strong>{total}</strong> von <strong>{scanned}</strong> gescannten Beiträgen für <strong>{lang}</strong>.','From'=>'Von','Front Page'=>'Startseite','FSE localisation: scaffold, translate, and fix links in Full Site Editing templates and template parts directly from this tab.'=>'FSE-Lokalisierung: Gerüst, Übersetzung und Korrektur von Links in Full Site Editing-Vorlagen und Vorlagenabschnitten direkt von diesem Tab aus.','FSE templates seeded from the active theme. Create then customise in the Site Editor.'=>'FSE-Vorlagen, die vom aktiven Theme vorgegeben sind. Erstelle sie und passe sie im Site Editor an.','Full Article'=>'Vollständiger Artikel','Full post'=>'Vollständiger Beitrag','General'=>'Allgemein','Generate'=>'Generieren','Generate Content'=>'Inhalt generieren','Generate content…'=>'Inhalt generieren…','Generate Excerpt'=>'Auszug generieren','Generate Meta Description'=>'Meta-Beschreibung generieren','Generated Content'=>'Generierter Inhalt','Generated meta description'=>'Generierte Meta-Beschreibung','Generating…'=>'Erzeuge…','Generation failed.'=>'Erstellung fehlgeschlagen.','Getting started'=>'Erste Schritte','Global AI preset'=>'Globale KI-Voreinstellung','Global default (%s)'=>'Globale Standardeinstellung (%s)','Glossary'=>'Glossar','Glossary entry added.'=>'Glossareintrag hinzugefügt.','Glossary entry removed.'=>'Glossareintrag entfernt.','Glossary Tab'=>'Glossar-Tab','Google (Gemini)'=>'Google (Gemini)','Hide'=>'Verbergen','Hints'=>'Hinweise','Home link text'=>'Startseiten-Link-Text','How it should appear in the translation. Type the same value as the source term to instruct the AI to preserve it verbatim.'=>'So soll er in der Übersetzung erscheinen. Gib denselben Wert wie den Quellbegriff ein, um die KI anzuweisen, ihn wortwörtlich zu bewahren.','https://github.com/leotiger/lingua-forge'=>'https://github.com/leotiger/lingua-forge','https://lingua-forge.com'=>'https://lingua-forge.com','Icon + label'=>'Icon + Label','Icon only'=>'Nur Icon','If checked, uninstalling the plugin will permanently delete all language assignments, translation relationships, meta descriptions, per-page presets, the AI glossary, and Translation Memory for every post on this site. This cannot be undone. Leave unchecked unless you are fully removing multilingual support from the site.'=>'Wenn aktiviert, werden bei der Deinstallation alle Sprachzuweisungen, Übersetzungsbeziehungen, Meta-Beschreibungen, Seiten-Voreinstellungen, das AI-Glossar und der Übersetzungsspeicher für jede Seite auf dieser Seite dauerhaft gelöscht. Dies kann nicht rückgängig gemacht werden. Nicht aktivieren, wenn du den mehrsprachigen Support vollständig entfernen möchtest.','Improve writing'=>'Schreiben verbessern','Informative'=>'Informativ','Input tokens'=>'Eingabe-Token','Install'=>'Installieren','Install a Language'=>'Eine Sprache installieren','Installing…'=>'Installiert…','Instructions (optional)'=>'Anweisungen (optional)','Instructions / key points'=>'Anweisungen / Schlüsselpunkte','Integration API'=>'Integrations-API','Internal Link Fixer'=>'Interner Link-Fehlerbeheber','Introduction only'=>'Nur Einführung','Invalid file reference.'=>'Ungültige Dateireferenz.','Invalid filename.'=>'Ungültiger Dateiname.','Invalid language.'=>'Ungültige Sprache.','Invalid locale code.'=>'Ungültiger Lokalisierungscode.','Invalid or primary language.'=>'Ungültige oder primäre Sprache.','Invalid post type.'=>'Ungültiger Beitragstyp.','Invalid template part.'=>'Ungültiger Vorlage-Teil.','Invalid template type.'=>'Ungültiger Vorlage-Typ.','Key points, ideas, or structure to build from…'=>'Wichtige Punkte, Ideen oder Strukturen, auf denen aufgebaut werden kann…','Keys are encrypted with AES-256-CBC before being stored in the WordPress database. The encryption secret is derived from your WordPress auth salts (wp-config.php), so plaintext keys never touch the database.'=>'Schlüssel werden vor der Speicherung in der WordPress-Datenbank mit AES-256-CBC verschlüsselt. Das Verschlüsselungsgeheimnis wird aus deinen WordPress-Auth-Salzen (wp-config.php) abgeleitet, sodass Klartext-Schlüssel die Datenbank nie berühren.','Language'=>'Sprache','Language %s installed successfully.'=>'Sprache %s erfolgreich installiert.','Language (optional)'=>'Sprache (optional)','Language installation is disabled on this server (DISALLOW_FILE_MODS is set).'=>'Die Sprachinstallation ist auf diesem Server deaktiviert (DISALLOW_FILE_MODS ist gesetzt).','Language installation is disabled on this server. The DISALLOW_FILE_MODS constant is set in wp-config.php. Install language packs manually via WP-CLI: wp language core install de_DE'=>'Die Sprachinstallation ist auf diesem Server deaktiviert. Die Konstante DISALLOW_FILE_MODS ist in wp-config.php gesetzt. Installiere Sprachpakete manuell via WP-CLI: wp language core install de_DE','Language label'=>'Sprachlabel','Language Overrides'=>'Sprachüberschreibungen','Language Overrides: manage custom .po/.mo override files for the Lingua Forge UI strings. Use this instead of editing plugin files directly — overrides survive updates.'=>'Sprachüberschreibungen: Verwalte benutzerdefinierte .po/.mo-Überschreibungsdateien für die Lingua Forge UI-Strings. Verwende dies anstelle der direkten Bearbeitung der Plugin-Dateien — Überschreibungen überleben Updates.','Language pack installation failed. The language may already be installed, the locale code may be incorrect, or your server may block file writes.'=>'Die Installation des Sprachpakets ist fehlgeschlagen. Die Sprache ist möglicherweise bereits installiert, der Lokalisierungscode ist falsch oder dein Server blockiert Dateischreibrechte.','Language Setup'=>'Sprachsetup','Language Switcher'=>'Sprachumschalter','Language switcher'=>'Sprachumschalter','Language-specific copies of the theme\'s template parts. Once scaffolded, templates are updated to reference the language-specific part.'=>'Sprachspezifische Kopien der Vorlagen-Teile des Themes. Nach der Erstellung werden die Vorlagen aktualisiert, um auf den sprachspezifischen Teil zu verweisen.','Language:'=>'Sprache:','Languages currently known to the router (derived from installed WordPress locale packs plus the primary language). Install additional language packs in the section below to make more languages available for routing and translation.'=>'Sprachen, die dem Router derzeit bekannt sind (abgeleitet von installierten WordPress-Lokalisierungspaketen plus der Primärsprache). Installiere zusätzliche Sprachpakete im unteren Abschnitt, um mehr Sprachen für Routing und Übersetzung verfügbar zu machen.','Last 30 days'=>'Letzte 30 Tage','Last 7 days'=>'Letzte 7 Tage','Lead paragraph (≤60 w)'=>'Einleitung (≤60 Wörter)','Leave a model field blank to use the built-in default for that tier. The placeholder text shows which model will be used.'=>'Lass ein Modellfeld leer, um das integrierte Standardmodell für diese Ebene zu verwenden. Der Platzhalter zeigt an, welches Modell verwendet wird.','Leave blank for brand names and language-agnostic terms that should be enforced regardless of which language we are translating from.'=>'Lass es leer für Markennamen und sprachunabhängige Begriffe, die unabhängig von der Sprache, aus der wir übersetzen, durchgesetzt werden sollen.','Leave blank to apply this entry to all target languages — ideal for brand names, abbreviations, and terms that must be preserved verbatim in every translation.'=>'Lass es leer, um diesen Eintrag auf alle Zielsprache anzuwenden – ideal für Markennamen, Abkürzungen und Begriffe, die in jeder Übersetzung wortwörtlich erhalten bleiben müssen.','Leave blank to keep the existing key. Enter a new value to replace it.'=>'Lass es frei, um den bestehenden Schlüssel beizubehalten. Gib einen neuen Wert ein, um ihn zu ersetzen.','Leave blank to use the built-in default. Clearing a saved override restores the default on next save.'=>'Lass es frei, um den integrierten Standard zu verwenden. Das Löschen einer gespeicherten Überschreibung stellt den Standard beim nächsten Speichern wieder her.','Legal / Compliance'=>'Rechtlich / Compliance','Legal / Compliance instructions'=>'Rechtliche / Compliance-Anweisungen','Light'=>'Leicht','Light (default — fast and cost-effective)'=>'Light (Standard – schnell und kostengünstig)','Light (fast and cost-effective — Haiku / Flash)'=>'Licht (schnell und kosteneffizient – Haiku / Flash)','Light: used for meta descriptions and excerpt generation — fast, low cost.'=>'Licht: Wird für Meta-Beschreibungen und Auszugserstellung verwendet — schnell, kostengünstig.','Limit results to pages in the given Lingua Forge language code.'=>'Ergebnisse auf Seiten im angegebenen Lingua Forge Sprachcode beschränken.','Limits'=>'Grenzen','Lingua Forge'=>'Lingua Forge','Lingua Forge adds multilingual routing, AI-powered translation, hreflang SEO tags, and a language switcher to your WordPress site.'=>'Lingua Forge fügt deiner WordPress-Seite mehrsprachiges Routing, KI-gestützte Übersetzung, hreflang-SEO-Tags und einen Sprachumschalter hinzu.','Lingua Forge AI Tools'=>'Lingua Forge KI-Tools','Lingua Forge restricts two Gutenberg features by default to keep editorial behavior consistent across languages. Opt in here when you need full Gutenberg / FSE capabilities.'=>'Lingua Forge beschränkt standardmäßig zwei Gutenberg-Funktionen, um das redaktionelle Verhalten in allen Sprachen konsistent zu halten. Hier kannst du dich anmelden, wenn du volle Gutenberg / FSE-Fähigkeiten benötigst.','Lingua Forge Settings'=>'Lingua Forge-Einstellungen','Lingua Forge uses two independent caching layers to avoid redundant AI API calls. Use the tabs below to inspect and manage each one.'=>'Lingua Forge verwendet zwei unabhängige Cache-Schichten, um redundante KI-API-Aufrufe zu vermeiden. Verwende die untenstehenden Tabs, um jede zu inspizieren und zu verwalten.','Lingua Forge uses two model tiers per provider:'=>'Lingua Forge verwendet zwei Modellstufen pro Anbieter:','Lingua Forge — Quick Translate'=>'Lingua Forge — Schnelles Übersetzen','Lingua Forge — Settings'=>'Lingua Forge — Einstellungen','link(s)'=>'Link(s)','Links'=>'Links','Load available languages'=>'Verfügbare Sprachen laden','Loading…'=>'Lädt…','Loco Translate stores its custom translations in wp-content/languages/loco/ — a location that can be silently wiped by a WP core update, plugin reinstall, or if Loco Translate itself is removed. Copying files here moves them into the Lingua Forge i18n-overrides directory, which persists through all of those events and is loaded automatically on every request.'=>'Loco Translate speichert seine benutzerdefinierten Übersetzungen im Verzeichnis wp-content/languages/loco/ – ein Ort, der bei einem WP-Kern-Update, Plugin-Neuinstallation oder bei Entfernung von Loco Translate still gelöscht werden kann. Das Kopieren der Dateien hier verschiebt sie in das Lingua Forge i18n-overrides-Verzeichnis, das all diesen Ereignissen standhält und bei jeder Anfrage automatisch geladen wird.','Loco Translate — Copy to Safe Storage'=>'Loco Translate – In sicheren Speicher kopieren','Lowest WordPress capability allowed to trigger AI features. Tightening this on multi-author sites prevents Contributors or trial accounts from running paid AI calls. Override per-feature via the linguaforge_required_capability filter.'=>'Niedrigste WordPress-Fähigkeit, die zum Auslösen von KI-Funktionen erlaubt ist. Das Verschärfen auf Multi-Autor-Websites verhindert, dass Mitwirkende oder Testkonten kostenpflichtige KI-Anfragen ausführen. Überschreibe pro Funktion via den linguaforge_required_capability-Filter.','Maintenance'=>'Wartung','Maintenance Tab'=>'Wartung-Tab','Make casual'=>'Umgangssprachlich machen','Make concise'=>'Kurz und bündig machen','Make formal'=>'Formell machen','Mark citations needed'=>'Zitate als notwendig markieren','Max context characters'=>'Max. Kontextzeichen','Max hints characters'=>'Max. Hinweise-Zeichen','Max input characters'=>'Maximale Eingabebuchstaben','Max output tokens'=>'Maximale Ausgaben-Tokens','Maximum characters accepted from the input field. Default: 8 000.'=>'Maximale akzeptierte Zeichen vom Eingabefeld. Standard: 8.000.','Maximum characters of existing post content passed to the AI as seed context when no Hints are provided. Default: 6 000.'=>'Maximale Zeichen des bestehenden Beitragsinhalts, die an die KI als Saatkontext übergeben werden, wenn keine Hinweise bereitgestellt werden. Standard: 6.000.','Maximum characters read from the Hints field. Default: 2 000.'=>'Maximale Zeichen, die aus dem Hinweise-Feld gelesen werden. Standard: 2.000.','Maximum number of characters of post content forwarded to the AI. 0 means no limit — the full content is always sent (recommended). Set a non-zero value only if your provider has a tight context window. A warning is written to the PHP error log whenever the content is trimmed.'=>'Maximale Anzahl der Zeichen des Beitragsinhalts, die an die KI weitergeleitet werden. 0 bedeutet kein Limit – der vollständige Inhalt wird immer gesendet (empfohlen). Stelle nur einen nicht-null Wert ein, wenn dein Anbieter ein enges Kontextfenster hat. Eine Warnung wird in das PHP-Fehlerprotokoll geschrieben, wenn der Inhalt gekürzt wird.','Maximum number of tokens the AI may produce in a single translation response. If a translation is silently cut off at the end, increase this value. Default: 16 000.'=>'Maximale Anzahl an Tokens, die die KI in einer einzigen Übersetzungsantwort produzieren darf. Wenn eine Übersetzung am Ende stillschweigend abgeschnitten wird, erhöhe diesen Wert. Standard: 16.000.','Maximum tokens the AI may produce per generation run. Raise this if full articles are being cut off. Default: 8 192.'=>'Maximale Tokens, die die KI pro Generationslauf produzieren darf. Erhöhe dies, wenn vollständige Artikel abgeschnitten werden. Standard: 8.192.','Maximum tokens the AI may produce per quick translation. Default: 2 000.'=>'Maximale Tokens, die die KI pro schnelle Übersetzung produzieren darf. Standard: 2.000.','Meta Description'=>'Meta-Beschreibung','Meta Description, Excerpt Generator'=>'Meta-Beschreibung, Exzerpt-Generator','Minimum role'=>'Mindestrolle','Missing pattern name or language.'=>'Fehlender Mustername oder Sprache.','Mode'=>'Modus','Model'=>'Modell','Model tier'=>'Modellstufe','Models'=>'Modelle','Models Tab (General)'=>'Modelle-Tab (Allgemein)','Most recent cached block'=>'Kürzlich zwischengespeicherter Block','Most recent cached response'=>'Kürzlich zwischengespeicherte Antwort','Multilingual routing, SEO meta tags, and AI content tools for WordPress. Combines language detection, URL routing, hreflang, meta descriptions, and AI-powered excerpt, meta, and translation features.'=>'Mehrsprachiges Routing, SEO-Meta-Tags und KI-Inhaltstools für WordPress. Kombiniert Spracherkennung, URL-Routing, hreflang, Meta-Beschreibungen sowie KI-gestützte Auszüge, Meta- und Übersetzungsfunktionen.','Name displayed in this language. Leave empty to use the source name.'=>'Name, der in dieser Sprache angezeigt wird. Leer lassen, um den Quellnamen zu verwenden.','Navigation'=>'Navigation','Navigation has no content to translate.'=>'Navigation hat keinen Inhalt zum Übersetzen.','Navigation not found.'=>'Navigation nicht gefunden.','Navigation posts are translated via the Router tab, not this button.'=>'Navigation-Posts werden über den Router-Tab übersetzt, nicht über diese Schaltfläche.','Navigation translation requires an active AI provider. Configure an API key in the API Keys tab.'=>'Navigation-Übersetzung erfordert einen aktiven KI-Anbieter. Konfiguriere einen API-Schlüssel im Tab API-Schlüssel.','Navigations'=>'Navigationen','Network error — could not reach the WordPress AJAX endpoint.'=>'Netzwerkfehler — konnte die WordPress AJAX-Schnittstelle nicht erreichen.','No %s version found in this translation group.'=>'Keine %s-Version in dieser Übersetzungsgruppe gefunden.','No AI provider configured.'=>'Kein KI-Anbieter konfiguriert.','No AI usage recorded in the selected window (%s). Pick a wider range above.'=>'Keine KI-Nutzung im ausgewählten Zeitraum (%s) aufgezeichnet. Wähle oben einen größeren Zeitraum.','No AI usage recorded yet. Once an editor runs a translation, generates a meta description, or uses any other AI feature, totals will appear here.'=>'Noch keine KI-Nutzung aufgezeichnet. Sobald ein Editor eine Übersetzung durchführt, eine Meta-Beschreibung generiert oder eine andere KI-Funktion nutzt, erscheinen hier die Gesamtsummen.','No API key configured for this provider.'=>'Für diesen Anbieter ist kein API-Schlüssel konfiguriert.','No built-in instructions — each AI feature uses its own tuned defaults. Fill in the Custom prompt instructions field below to add your own site-wide rules.'=>'Keine integrierten Anweisungen — jede KI-Funktion verwendet ihre eigenen abgestimmten Standardwerte. Fülle das Feld für benutzerdefinierte Anweisungen unten aus, um eigene siteweite Regeln hinzuzufügen.','No custom Loco Translate files found yet. They appear here once you save a translation in Loco Translate.'=>'Noch keine benutzerdefinierten Loco Translate-Dateien gefunden. Sie erscheinen hier, sobald du eine Übersetzung in Loco Translate speicherst.','No file was selected.'=>'Keine Datei ausgewählt.','No glossary entries match the current filter. Clear the filter to see all entries, or add a new entry below.'=>'Keine Glossareinträge entsprechen dem aktuellen Filter. Entferne den Filter, um alle Einträge zu sehen, oder füge unten einen neuen Eintrag hinzu.','No glossary entries yet. Add one below to start enforcing terminology in translations.'=>'Noch keine Glossareinträge. Füge unten einen hinzu, um die Terminologie in Übersetzungen durchzusetzen.','No internal links found to update.'=>'Keine internen Links zum Aktualisieren gefunden.','No language-specific template parts found to map.'=>'Keine sprachspezifischen Vorlage-Teile zum Abbilden gefunden.','No navigation references needed updating.'=>'Keine Navigationsreferenzen zum Aktualisieren erforderlich.','No override files uploaded yet.'=>'Noch keine Überschreibungsdateien hochgeladen.','No response from provider — check the error log for details.'=>'Keine Antwort vom Anbieter — Überprüfe das Fehlerprotokoll für Details.','No secondary languages configured. Install a language pack above to enable template scaffolding.'=>'Keine sekundären Sprachen konfiguriert. Installiere ein Sprachpaket oben, um die Vorlagenerstellung zu aktivieren.','No source content found to translate.'=>'Kein Quellinhalt zum Übersetzen gefunden.','No source page linked yet.'=>'Noch keine Quellseite verknüpft.','No template part references needed updating.'=>'Keine Vorlage-Teile-Referenzen zum Aktualisieren erforderlich.','No {lang} translation registered (TRID missing)'=>'Keine {lang}-Übersetzung registriert (TRID fehlt)','Notes'=>'Notizen','Notice message'=>'Hinweisnachricht','Notice settings'=>'Hinweis-Einstellungen','Oldest cached block'=>'Ältester zwischengespeicherter Block','Oldest cached response'=>'Älteste zwischengespeicherte Antwort','Only .mo files are accepted.'=>'Nur .mo-Dateien werden akzeptiert.','OpenAI (GPT)'=>'OpenAI (GPT)','Optional context for editors (e.g. "ASIC = Application-Specific Integrated Circuit; preserve in English in technical contexts").'=>'Optionaler Kontext für Redakteure (z.B. "ASIC = Application-Specific Integrated Circuit; in technischen Kontexten auf Englisch belassen").','Output'=>'Ausgabe','Output tokens'=>'Ausgabe-Token','overridden'=>'überschrieben','Override file deleted.'=>'Überschreibungsdatei gelöscht.','Override file uploaded successfully.'=>'Überschreibungsdatei erfolgreich hochgeladen.','Overrides the AI preset for Translation and Content Generation on this page. All other features always use the global preset.'=>'Überschreibt die KI-Voreinstellung für Übersetzung und Inhaltserstellung auf dieser Seite. Alle anderen Funktionen verwenden immer die globale Voreinstellung.','Overrides the AI preset for Translation and Content Generation on this page. Site-wide custom prompt instructions (Settings → Behavior) are always appended to every request regardless of this selection.'=>'Überschreibt die KI-Voreinstellung für Übersetzung und Inhaltserstellung auf dieser Seite. Site-weite benutzerdefinierte Anweisungen (Einstellungen → Verhalten) werden immer an jede Anfrage angehängt, unabhängig von dieser Auswahl.','Overview'=>'Übersicht','Page'=>'Seite','Part'=>'Teil','Paste a footnote, sentence, or any snippet here…'=>'Füge hier eine Fußnote, einen Satz oder einen beliebigen Ausschnitt ein…','Paste text, or select text in the editor first…'=>'Füge Text ein oder wähle zuerst Text im Editor aus…','Paste text, or select text on the page first…'=>'Füge Text ein oder wähle zuerst Text auf der Seite aus…','Paste your API key…'=>'Füge deinen API-Schlüssel ein…','Path prefix — example.com/de/'=>'Pfadpräfix — example.com/de/','Pattern'=>'Muster','Pattern has no content to translate.'=>'Muster hat keinen zu übersetzenden Inhalt.','Pattern not found.'=>'Muster nicht gefunden.','Pattern translated and saved. Copy the content into your CPT post via the block editor Pattern inserter or use it as a starting point for a Reusable Block.'=>'Muster übersetzt und gespeichert. Kopiere den Inhalt in deinen CPT-Beitrag über den Block-Editor Muster-Insertor oder nutze es als Ausgangspunkt für einen wiederverwendbaren Block.','Pattern translation failed.'=>'Musterübersetzung fehlgeschlagen.','Per-post cache for AI-generated translations, meta descriptions, excerpts, and content. Always active — no separate toggle required. Entries are invalidated automatically when the content or AI provider/model changes. Use the toolbar "↺ Re-translate" button or click Clear below to force a fresh API call.'=>'Per-Beitrag-Cache für KI-generierte Übersetzungen, Meta-Beschreibungen, Auszüge und Inhalte. Immer aktiv — kein separater Schalter erforderlich. Einträge werden automatisch ungültig, wenn sich Inhalt oder KI-Anbieter/-Modell ändert. Verwende die Schaltfläche "↺ Neu übersetzen" in der Symbolleiste oder klicke auf "Leeren" unten, um einen frischen API-Aufruf zu erzwingen.','Permalink rules flushed successfully.'=>'Permalink-Regeln erfolgreich gelöscht.','Permission denied.'=>'Zugriff verweigert.','Persuasive'=>'Überzeugend','PHP constant'=>'PHP-Konstante','Pin terms that must not be translated or must always be rendered in a specific way (e.g. brand names, product names, acronyms). Glossary constraints are injected into every AI translation request for all features: post translation, meta description, excerpt, and FSE template translation.'=>'Markiere Begriffe, die nicht übersetzt werden sollen oder immer auf eine bestimmte Weise dargestellt werden müssen (z.B. Markennamen, Produktnamen, Akronyme). Glossar-Einschränkungen werden in jede KI-Übersetzungsanfrage für alle Funktionen eingebunden: Beitrag-Übersetzung, Meta-Beschreibung, Auszug und FSE-Vorlagenübersetzung.','Plain language'=>'Einfache Sprache','Please enter some instructions first…'=>'Bitte gib zuerst Anweisungen ein…','Please enter some text first…'=>'Bitte gib zuerst einen Text ein…','Post'=>'Beitrag','Post not found.'=>'Beitrag nicht gefunden.','Post Types'=>'Beitragstypen','Prefilled from excerpt. Edit to override.'=>'Vordefiniert aus Auszug. Bearbeite, um zu überschreiben.','Primary Language'=>'Primärsprache','Primary language'=>'Primärsprache','Primary language saved.'=>'Primärsprache gespeichert.','Primary language: the language your existing content is written in. All translations are produced from this language; changing it does not move or delete any posts.'=>'Primäre Sprache: die Sprache, in der dein bestehender Inhalt geschrieben ist. Alle Übersetzungen werden aus dieser Sprache erstellt; eine Änderung verschiebt oder löscht keine Beiträge.','Processing…'=>'Verarbeite…','Provider'=>'Anbieter','Provider returned no text. Check the WordPress error log for the detailed failure reason.'=>'Der Anbieter hat keinen Text zurückgegeben. Überprüfe das WordPress-Fehlerprotokoll für die detaillierte Fehlerursache.','Quality'=>'Qualität','Quality (default — Sonnet / GPT-4o / Gemini Pro)'=>'Qualität (Standard – Sonnet / GPT-4o / Gemini Pro)','Quality (Sonnet / GPT-4o / Gemini Pro)'=>'Qualität (Sonnet / GPT-4o / Gemini Pro)','Quality: used for post translation and content generation — higher quality, higher cost.'=>'Qualität: Wird für Beitrag-Übersetzung und Inhaltserstellung verwendet — höhere Qualität, höhere Kosten.','Quick Translate'=>'Schnelle Übersetzung','Quick Translation'=>'Schnelle Übersetzung','Quick Translation is used for snippet/chunk mode — short passages translated on demand from the toolbar, editor, or block popovers. It uses a separate, lighter configuration from the full-page translation to keep responses fast and cost-effective.'=>'Schnelle Übersetzung wird im Snippet-/Chunk-Modus verwendet – kurze Passagen, die auf Abruf aus der Symbolleiste, dem Editor oder den Block-Popovers übersetzt werden. Es verwendet eine separate, leichtere Konfiguration als die Vollseitenübersetzung, um schnelle und kostengünstige Antworten zu gewährleisten.','Re-enables Gutenberg\'s canLockBlocks. Useful for editorial templates that need to prevent contributors from moving or deleting specific blocks.'=>'Aktiviert wieder Gutenberg\'s canLockBlocks. Nützlich für redaktionelle Vorlagen, die verhindern sollen, dass Mitwirkende bestimmte Blöcke verschieben oder löschen.','Re-enables supportsTemplateMode. Core to Full-Site-Editing workflows where post-level template overrides are intentional.'=>'Aktiviert supportsTemplateMode. Kern für Full-Site-Editing-Workflows, bei denen Beitragsübergreifende Vorlagenüberschreibungen beabsichtigt sind.','Re-generates and updates the cached result.'=>'Erzeugt und aktualisiert das zwischengespeicherte Ergebnis.','Re-scan'=>'Neu scannen','Re-scanning…'=>'Neu scannen…','Re-translate'=>'Neu übersetzen','Redirect visitors to their preferred language based on the browser\'s Accept-Language header'=>'Leite Besucher basierend auf dem Accept-Language-Header ihres Browsers auf ihre bevorzugte Sprache um','Refine further — e.g. "make it shorter" or "use a formal tone"…'=>'Weiter verfeinern — z.B. "kürzer machen" oder "formelleren Ton verwenden"…','Refine further:'=>'Weiter verfeinern:','Refinement'=>'Verfeinerung','Refinement failed — please try again.'=>'Verfeinerung fehlgeschlagen — bitte versuche es erneut.','Refining…'=>'Verfeinere…','Regenerates WordPress rewrite rules so URL prefixes, language-specific slugs, and archive rewrites are all in sync. Necessary after changing the primary language or adding new language support.'=>'Regeneriert die Rewrite-Regeln von WordPress, sodass URL-Präfixe, sprachspezifische Slugs und Archiv-Umleitungen synchron sind. Notwendig nach Änderung der Primärsprache oder Hinzufügen neuer Sprachunterstützung.','Remove stored key'=>'Gespeicherten Schlüssel entfernen','Report an issue on GitHub'=>'Melde ein Problem auf GitHub','Request failed — please try again.'=>'Anfrage fehlgeschlagen — bitte versuche es erneut.','Request failed.'=>'Anfrage fehlgeschlagen.','Request failed. Check your connection.'=>'Anfrage fehlgeschlagen. Überprüfe deine Verbindung.','Request failed. Please try again.'=>'Anfrage fehlgeschlagen. Bitte versuche es erneut.','Requests'=>'Anfragen','Reset'=>'Zurücksetzen','Result will appear here…'=>'Das Ergebnis erscheint hier…','Retranslate'=>'Erneut übersetzen','Retranslating…'=>'Erneut übersetzen…','Review carefully — links and slugs not updated.'=>'Überprüfe sorgfältig — Links und Slugs wurden nicht aktualisiert.','Review translation before applying'=>'Überprüfung der Übersetzung vor dem Anwenden','Revise'=>'Überarbeiten','Revision'=>'Überarbeitung','Revision Type'=>'Überarbeitungsart','Router'=>'Router','Router Tab'=>'Router-Tab','Save Debug Setting'=>'Debug-Einstellung speichern','Save Router Settings'=>'Router-Einstellungen speichern','Save Settings'=>'Einstellungen speichern','Save the post to persist changes.'=>'Der Beitrag wird gespeichert, um Änderungen zu sichern.','Save Uninstall Setting'=>'Deinstallations-Einstellung speichern','Saved to the meta description field when you apply.'=>'Beim Anwenden im Meta-Beschreibungsfeld gespeichert.','Scan failed: '=>'Scan fehlgeschlagen: ','Scan request failed. Please try again.'=>'Scan-Anfrage fehlgeschlagen. Bitte versuche es erneut.','Scanning posts for broken language links…'=>'Suche nach defekten Sprachlinks in Beiträgen…','Search'=>'Suche','Search Results'=>'Suchergebnisse','Security check failed — file path is not permitted.'=>'Sicherheitsüberprüfung fehlgeschlagen – Dateipfad ist nicht erlaubt.','Select a language to manage its FSE templates, template parts, and navigation menus.'=>'Wähle eine Sprache, um ihre FSE-Vorlagen, Vorlage-Teile und Navigationsmenüs zu verwalten.','Select language'=>'Sprache auswählen','SEO character-count info'=>'SEO-Zeichenzählinfo','Server setup (subdomain)'=>'Servereinrichtung (Subdomain)','Sets the default AI behaviour for all features site-wide. Individual posts can override this for Translation and Content Generation via the Lingua Forge meta box.'=>'Legt das Standardverhalten der KI für alle Funktionen site-weit fest. Einzelne Beiträge können dies für Übersetzungen und Inhaltserstellung über die Meta-Box von Lingua Forge überschreiben.','Settings'=>'Einstellungen','Settings saved.'=>'Einstellungen gespeichert.','Show home link'=>'Startseite-Link anzeigen','Shown when no translation exists for the visitor\'s language.'=>'Wird angezeigt, wenn keine Übersetzung für die Sprache des Besuchers vorhanden ist.','Single'=>'Einzeln','Single %s'=>'Einzeln %s','Single: %s'=>'Einzeln: %s','Site-wide ceiling on AI requests per UTC day (counts both Toolbar translations and block revisions). Counter resets at UTC midnight. Set to 0 to disable the cap.'=>'Gesamtgrenze für KI-Anfragen pro UTC-Tag (zählt sowohl Toolbar-Übersetzungen als auch Block-Revisionen). Zählt bei UTC-Midnight zurück. Setze auf 0, um die Begrenzung zu deaktivieren.','Size'=>'Größe','Some link fixes failed.'=>'Einige Link-Reparaturen sind fehlgeschlagen.','Some nav ref fixes failed.'=>'Einige Navigationsreferenz-Reparaturen sind fehlgeschlagen.','Some part fixes failed.'=>'Einige Teile-Reparaturen sind fehlgeschlagen.','Some parts could not be created.'=>'Einige Teile konnten nicht erstellt werden.','Some templates could not be created.'=>'Einige Vorlagen konnten nicht erstellt werden.','Some translations failed.'=>'Einige Übersetzungen sind fehlgeschlagen.','Source file not found.'=>'Quelldatei nicht gefunden.','Source lang'=>'Quell-Sprache','Source language'=>'Quellsprache','Source term'=>'Quellbegriff','Standard'=>'Standard','Standard uses each feature\'s own tuned temperature: Translation T=0.2 (precise), Quick Translate T=0.4, Content Generator T=0.6 (creative). The other presets apply a single fixed temperature across all features.'=>'Standard verwendet die eigene abgestimmte Temperatur jeder Funktion: Übersetzung T=0.2 (präzise), Schnelle Übersetzung T=0.4, Inhaltserstellung T=0.6 (kreativ). Die anderen Voreinstellungen verwenden eine einzelne feste Temperatur für alle Funktionen.','Status'=>'Status','Status / Actions'=>'Status / Aktionen','Storytelling'=>'Storytelling','Strict-preservation mode for legal, regulatory, medical, or technical content. When on, every AI feature uses a low sampling temperature and appends the addendum below to its system prompt — terminology, article numbers, units, brand names, and regulatory language are preserved verbatim rather than paraphrased.'=>'Strenger Erhaltungsmodus für rechtliche, regulatorische, medizinische oder technische Inhalte. Wenn aktiviert, verwendet jede KI-Funktion eine niedrige Abtasttemperatur und fügt die nachstehende Ergänzung an den Systemprompt an — Terminologie, Artikelnumer, Einheiten, Markennamen und regulatorische Sprache werden wortwörtlich beibehalten, anstatt umformuliert zu werden.','Structured Outline'=>'Strukturierte Gliederung','Subdomain mode requires your web server to point all language subdomains (e.g. de.example.com) to this WordPress installation. After switching modes, flush permalink rules and clear any caches. If your home URL includes www (e.g. www.example.com), use the lf_base_domain filter to set the bare apex domain so subdomains are constructed correctly.'=>'Der Subdomain-Modus erfordert, dass dein Webserver alle Sprach-Subdomains (z.B. de.example.com) auf diese WordPress-Installation zeigt. Nach dem Wechsel des Modus, leere die Permalink-Regeln und lösche alle Caches. Wenn deine Start-URL www enthält (z.B. www.example.com), verwende den lf_base_domain Filter, um die reine Domain festzulegen, damit die Subdomains korrekt aufgebaut werden.','Subdomain — de.example.com/'=>'Subdomain — de.example.com/','Supported providers: Anthropic (Claude), OpenAI (GPT), Google (Gemini). Only one provider is active at a time. Select the active provider on the General tab.'=>'Unterstützte Anbieter: Anthropic (Claude), OpenAI (GPT), Google (Gemini). Nur ein Anbieter ist gleichzeitig aktiv. Wähle den aktiven Anbieter im Allgemeinen-Tab.','T=%s'=>'T=%s','T=0.2–0.6, per feature'=>'T=0.2–0.6, pro Funktion','Target lang'=>'Ziel-Sprache','Target Language'=>'Zielsprache','Target language'=>'Zielsprache','Target term'=>'Zielbegriff','Target: 140–160 chars for optimal SERP display'=>'Ziel: 140–160 Zeichen für optimale SERP-Anzeige','Technical'=>'Technisch','Technical / Scientific'=>'Technisch / Wissenschaftlich','Technical / Scientific instructions'=>'Technische / Wissenschaftliche Anweisungen','Template "%s" already exists.'=>'Vorlage "%s" existiert bereits.','Template "{expected}" does not exist — create it in the Site Editor first.'=>'Template "{expected}" existiert nicht — erstelle es zuerst im Site Editor.','Template has no content.'=>'Vorlage hat keinen Inhalt.','Template mode'=>'Vorlagenmodus','Template not found or not stored in the database.'=>'Vorlage nicht gefunden oder nicht in der Datenbank gespeichert.','Template part "%s" already exists.'=>'Vorlage-Teil "%s" existiert bereits.','Template part has no content.'=>'Vorlage-Teil hat keinen Inhalt.','Template part not found or not stored in the database.'=>'Vorlage-Teil nicht gefunden oder nicht in der Datenbank gespeichert.','Template Parts'=>'Vorlagen-Teile','Templates'=>'Vorlagen','Test connection'=>'Verbindung testen','Testing…'=>'Wird getestet…','Text domain / locale'=>'Textdomain / Sprache','Text to translate'=>'Zu übersetzender Text','The API Response Cache stores the raw result of every AI request — translation, meta description, excerpt, and content generation — keyed by a hash of the inputs (content, language pair, provider, model). Subsequent requests with identical inputs are served from the cache with no API call. The cache is different from Translation Memory: Translation Memory operates at the block level and is shared across posts; the API Response Cache operates at the feature level and is keyed per post.'=>'Der API-Antwort-Cache speichert das rohe Ergebnis jeder KI-Anfrage — Übersetzung, Meta-Beschreibung, Auszug und Inhaltserstellung —, basierend auf einem Hash der Eingaben (Inhalt, Sprachpaar, Anbieter, Modell). Nachfolgende Anfragen mit identischen Eingaben werden aus dem Cache bedient, ohne API-Aufruf. Der Cache unterscheidet sich vom Übersetzungsspeicher: Der Übersetzungsspeicher arbeitet auf Blockebene und ist über Beiträge hinweg geteilt; der API-Antwort-Cache arbeitet auf Feature-Ebene und ist pro Beitrag gekennzeichnet.','The editor did not accept the content — please try again.'=>'Der Editor hat den Inhalt nicht akzeptiert — bitte versuche es erneut.','The Light tier uses the fast model configured in the Models table above (default: Haiku / Flash). Switch to Quality if you need the same translation accuracy as full-page mode for snippets.'=>'Die Light-Stufe verwendet das schnelle Modell, das in der oben stehenden Modellauswahl konfiguriert ist (Standard: Haiku / Flash). Wechsle zu Qualität, wenn du die gleiche Übersetzungsgenauigkeit wie im Vollseitenmodus für Snippets benötigst.','The phrase as it appears in the source text.'=>'Der Ausdruck, wie er im Quelltext erscheint.','The primary language is always served at the root of your site — no URL prefix in path mode, no language subdomain in subdomain mode. All other languages use either a /lang/ path prefix (e.g. example.com/de/) or a language subdomain (e.g. de.example.com), depending on the URL structure setting below.'=>'Die primäre Sprache wird immer an der Wurzel deiner Seite bedient — kein URL-Präfix im Pfadmodus, keine Sprach-Subdomain im Subdomain-Modus. Alle anderen Sprachen verwenden entweder ein /lang/ Pfadpräfix (z.B. example.com/de/) oder eine Sprach-Subdomain (z.B. de.example.com), abhängig von der unten stehenden URL-Struktur-Einstellung.','The source page has no footnotes.'=>'Die Quellseite hat keine Fußnoten.','The upload failed — please try again.'=>'Der Upload ist fehlgeschlagen – bitte versuche es erneut.','These footnotes come from the source page and are shown here for reference only. Add them to this page using the block editor.'=>'Diese Fußnoten stammen von der Quellseite und werden hier nur zur Referenz angezeigt. Füge sie mit dem Blockeditor auf dieser Seite hinzu.','This is the source page. Footnotes are edited directly in the block editor.'=>'Dies ist die Quellseite. Fußnoten werden direkt im Blockeditor bearbeitet.','This key is currently supplied by a server %s and cannot be removed here. Enter a new key above to override it with a database value.'=>'Dieser Schlüssel wird derzeit von einem Server %s bereitgestellt und kann hier nicht entfernt werden. Gib oben einen neuen Schlüssel ein, um ihn mit einem Datenbankwert zu überschreiben.','Tip: to reset a model to the built-in default, clear the field and save.'=>'Tipp: Um ein Modell auf den integrierten Standard zurückzusetzen, lösche das Feld und speichere.','To use a custom encryption secret (instead of the derived wp_salt value), add this to wp-config.php:'=>'Um einen benutzerdefinierten Verschlüsselungsgeheimnis zu verwenden (anstatt des abgeleiteten wp_salt-Werts), füge dies in wp-config.php hinzu:','Today'=>'Heute','Token consumption rolled up by feature, provider, and model. Recorded on every successful AI call; Test Connection pings are deliberately excluded so they don\'t skew the totals. The underlying table aggregates daily — pick a window below to view it.'=>'Token-Verbrauch nach Funktion, Anbieter und Modell zusammengefasst. Aufgezeichnet bei jedem erfolgreichen KI-Aufruf; Testverbindungspings sind absichtlich ausgeschlossen, damit sie die Gesamtsumme nicht verfälschen. Die zugrunde liegende Tabelle aggregiert täglich — wähle unten ein Zeitfenster, um sie anzuzeigen.','Tone'=>'Ton','tone'=>'Ton','Tone:'=>'Ton:','Too many AI requests. Please retry in %d seconds.'=>'Zu viele KI-Anfragen. Bitte versuche es in %d Sekunden erneut.','Total'=>'Gesamt','Total tokens'=>'Gesamt-Token','Translate'=>'Übersetzen','Translate / Revise'=>'Übersetzen / Überarbeiten','Translate / Revise block'=>'Block übersetzen / überarbeiten','Translate all'=>'Alles übersetzen','Translate chunk'=>'Abschnitt übersetzen','Translate Content'=>'Inhalt übersetzen','Translate missing'=>'Fehlende Übersetzung','Translate page…'=>'Seite übersetzen…','Translated content'=>'Übersetzter Inhalt','Translated Names'=>'Übersetzte Namen','Translated title'=>'Übersetzter Titel','Translated to:'=>'Übersetzt nach:','Translated. Review in the Site Editor — internal links, navigation URLs, and template slugs are not updated automatically.'=>'Übersetzt. Überprüfe im Site Editor — interne Links, Navigations-URLs und Template-Slugs werden nicht automatisch aktualisiert.','Translating…'=>'Übersetze…','Translation'=>'Übersetzung','Translation Caching'=>'Übersetzungscaching','Translation found but permalink could not be generated'=>'Übersetzung gefunden, aber Permalink konnte nicht generiert werden','Translation Limits'=>'Übersetzungsbegrenzungen','Translation Limits & Behavior'=>'Übersetzungsgrenzen & Verhalten','Translation Limits: control which user roles can trigger AI translation, and set a monthly token budget. Exceeding the budget suspends AI calls until the month resets.'=>'Übersetzungsgrenzen: Steuere, welche Benutzerrollen die KI-Übersetzung auslösen können, und lege ein monatliches Token-Budget fest. Wenn das Budget überschritten wird, werden KI-Anfragen bis zum Monatswechsel ausgesetzt.','Translation Memory'=>'Übersetzungsspeicher','Translation Memory caches AI results by content hash, language pair, provider, and model. Editing a post invalidates the cache entry so the next translate call gets a fresh result.'=>'Das Übersetzungsspeicher-Cache speichert KI-Ergebnisse anhand von Inhalts-Hash, Sprachpaar, Anbieter und Modell. Das Bearbeiten eines Beitrags invalidiert den Cache-Eintrag, sodass der nächste Übersetzungsaufruf ein frisches Ergebnis erhält.','Translation Memory cleared. %d cached block was removed.'=>'Übersetzungsspeicher gelöscht. %d zwischengespeicherter Block wurde entfernt.' . "\0" . 'Übersetzungsspeicher gelöscht. %d zwischengespeicherte Blöcke wurden entfernt.','Translation Memory: stores the full translated post per content hash. Clear it when you want to force a retranslation of all posts regardless of whether their content changed.'=>'Übersetzungsspeicher: Speichert den vollständigen übersetzten Beitrag pro Inhalts-Hash. Lösche ihn, wenn du eine erneute Übersetzung aller Beiträge erzwingen möchtest, unabhängig davon, ob sich deren Inhalt geändert hat.','Translation workflow'=>'Übersetzungsworkflow','Translation, Content Generator'=>'Übersetzung, Inhaltserstellung','Type'=>'Typ','Uli Hake'=>'Uli Hake','Uninstall Behaviour'=>'Deinstallationsverhalten','Uninstall setting saved.'=>'Deinstallations-Einstellung gespeichert.','unknown error'=>'Unbekannter Fehler','Unknown provider.'=>'Unbekannter Anbieter.','Up'=>'Nach oben','Upload .mo file'=>'.mo-Datei hochladen','Upload compiled .mo files to override third-party plugin strings for specific locales — for example, a custom VikBooking translation that uses "apartment" instead of "room". Files must follow the WordPress naming convention: {textdomain}-{locale}.mo (e.g. vikbooking-ca.mo). They are stored in the uploads folder and survive plugin updates.'=>'Kompilierte .mo-Dateien hochladen, um Strings von Drittanbieter-Plugins für bestimmte Sprachen zu überschreiben – zum Beispiel eine benutzerdefinierte VikBooking-Übersetzung, die "Apartment" anstelle von "Zimmer" verwendet. Dateien müssen dem WordPress-Namensschema folgen: {textdomain}-{locale}.mo (z.B. vikbooking-ca.mo). Sie werden im Upload-Ordner gespeichert und überleben Plugin-Updates.','Upload Override'=>'Überschreibung hochladen','URL could not be mapped to a post — check the link target exists'=>'URL konnte keinem Beitrag zugeordnet werden — überprüfe, ob das Ziel existiert','URL structure'=>'URL-Struktur','URL structure: path-prefix mode (example.com/de/) requires no server changes. Subdomain mode (de.example.com) requires a wildcard DNS record, a wildcard SSL certificate, and a web server configuration change — see the Server Setup guide.'=>'URL-Struktur: Pfadpräfix-Modus (example.com/de/) erfordert keine Serveränderungen. Subdomain-Modus (de.example.com) benötigt einen Wildcard-DNS-Eintrag, ein Wildcard-SSL-Zertifikat und eine Änderung der Webserver-Konfiguration — siehe die Server-Einrichtungsanleitung.','Use the tabs across the top of this page to configure each area. Changes to the Router tab take effect immediately; changes to AI keys and model settings apply to the next AI request.'=>'Verwende die Tabs oben auf dieser Seite, um jeden Bereich zu konfigurieren. Änderungen am Router-Tab treten sofort in Kraft; Änderungen an KI-Schlüsseln und Modelleinstellungen gelten für die nächste KI-Anfrage.','User-managed terminology table per language pair. Entries are appended to the translation system prompt so the AI uses preferred terms consistently — critical for domain vocabulary ("kWp", "PPA", "interconnection point"), brand names that must not translate, and standardised regulatory phrasing. Both language fields are optional: leave "Source language" blank to apply the entry regardless of which language you are translating from; leave "Target language" blank to apply it to all target languages at once.'=>'Benutzerverwaltete Terminologietabelle pro Sprachpaar. Einträge werden an den Übersetzungssystemprompt angehängt, damit die KI bevorzugte Begriffe konsequent verwendet – entscheidend für Fachvokabular ("kWp", "PPA", "Anschlussstelle"), Markennamen, die nicht übersetzt werden dürfen, und standardisierte regulatorische Formulierungen. Beide Sprachfelder sind optional: Lass "Quellsprache" leer, um den Eintrag unabhängig von der Sprache, aus der du übersetzt, anzuwenden; lass "Zielsprache" leer, um ihn auf alle Zielsprache gleichzeitig anzuwenden.','Using custom meta description.'=>'Verwendung einer benutzerdefinierten Meta-Beschreibung.','View'=>'Ansicht','View built-in default'=>'Integrierten Standard anzeigen','View details'=>'Details anzeigen','View Lingua Forge details'=>'Details zu Lingua Forge anzeigen','Visit plugin site'=>'Plugin-Seite besuchen','Warning:'=>'Warnung:','When debug logging is enabled (via the toggle below or by defining LINGUAFORGE_AI_DEBUG in wp-config.php), the Translation and FSE template translation features write their raw AI prompts and responses to disk for troubleshooting. Use this section to monitor that output and clear it once you have what you need — the files can grow quickly on large pages. Configure the destination directory via the linguaforge_debug_dir filter.'=>'Wenn das Debug-Logging aktiviert ist (über den Schalter unten oder durch die Definition von LINGUAFORGE_AI_DEBUG in wp-config.php), schreiben die Übersetzungs- und FSE-Template-Übersetzungsfunktionen ihre rohen AI-Aufforderungen und Antworten zur Fehlerbehebung auf die Festplatte. Nutze diesen Abschnitt, um diese Ausgabe zu überwachen und sie zu löschen, sobald du hast, was du brauchst — die Dateien können bei großen Seiten schnell wachsen. Konfiguriere das Zielverzeichnis über den linguaforge_debug_dir-Filter.','When enabled, first-time visitors with no language cookie and no language prefix in the URL are redirected to the closest matching language version. The redirect is skipped if the browser\'s preferred language is not among the active router languages. Once a visitor selects a language via the switcher, the cookie takes priority and the browser header is ignored on all future visits.'=>'Wenn aktiviert, werden Erstbesucher ohne Sprach-Cookie und ohne Sprachpräfix in der URL auf die nächstgelegene passende Sprachversion umgeleitet. Die Umleitung wird übersprungen, wenn die bevorzugte Sprache des Browsers nicht zu den aktiven Router-Sprachen gehört. Sobald ein Besucher eine Sprache über den Schalter auswählt, hat das Cookie Vorrang und der Browser-Header wird bei zukünftigen Besuchen ignoriert.','Which model tier to use for full-page translation. Quality uses the model configured in the Models table above and is recommended for accurate, long-form translation. Switch to Light only if speed or cost is the priority and the content is short.'=>'Welche Modellstufe für die Vollseitenübersetzung verwenden. Qualität nutzt das im obigen Modelle-Tabelle konfigurierte Modell und wird für genaue, längere Übersetzungen empfohlen. Wechsle nur zu Licht, wenn Geschwindigkeit oder Kosten Priorität haben und der Inhalt kurz ist.','WP-CLI reference'=>'WP-CLI Referenz','Write AI prompts and responses to disk for troubleshooting'=>'AI-Aufforderungen und Antworten zur Fehlerbehebung auf die Festplatte schreiben','You can also define keys as constants or environment variables (e.g. in wp-config.php). Those sources are used automatically as a fallback when no database key is stored.'=>'Du kannst Schlüssel auch als Konstanten oder Umweltvariablen definieren (z.B. in wp-config.php). Diese Quellen werden automatisch als Fallback verwendet, wenn kein Datenbankschlüssel gespeichert ist.','You do not have permission to manage these settings.'=>'Du hast keine Berechtigung, diese Einstellungen zu verwalten.','You do not have permission to read this post.'=>'Du hast keine Berechtigung, diesen Beitrag zu lesen.','{n} stale path(s)'=>'{n} veralteter Pfad(e)','— Any source language —'=>'— Beliebige Quellsprache —','— Any target language —'=>'— Beliebige Zielsprache —','— Any target —'=>'— Beliebige Zielsprache —','— Any —'=>'— Beliebig —','— auto-detect —'=>'— automatisches Erkennen —','— select a language —'=>'— wähle eine Sprache —','— toggle in Settings → Behavior.'=>'— Schalter in Einstellungen → Verhalten.','← Back'=>'← Zurück','↑ Detected from current post'=>'↑ Erkannt vom aktuellen Beitrag','↺ Re-translate'=>'↺ Erneut übersetzen','↺ Refine'=>'↺ Verfeinern','↺ Refresh'=>'↺ Aktualisieren','↺ Refreshing…'=>'↺ Aktualisieren…','⚠ Borderline'=>'⚠ Grenzwertig','⚠ No <strong>{lang}</strong> posts found. Make sure all translated posts have their Language meta set to <strong>{lang}</strong> in the Language metabox.'=>'⚠ Keine <strong>{lang}</strong>-Beiträge gefunden. Stelle sicher, dass alle übersetzten Beiträge ihre Sprach-Meta auf <strong>{lang}</strong> gesetzt haben.','⚠ No changes'=>'⚠ Keine Änderungen','⚠ No changes — re-scan?'=>'⚠ Keine Änderungen — erneut scannen?','✅ Fixed ({n})'=>'✅ Behoben ({n})','✅ No broken links or template mismatches found for <strong>{lang}</strong>. Scanned <strong>{scanned}</strong> post(s) and page(s) — all checks passed. Template part links (header, footer, sidebar) are not included here — use the Fix Template Parts button to check those separately.'=>'✅ Keine defekten Links oder Template-Fehler für <strong>{lang}</strong> gefunden. Es wurden <strong>{scanned}</strong> Beitrag(e) und Seite(n) gescannt — alle Prüfungen bestanden. Links zu Template-Teilen (Header, Footer, Sidebar) sind hier nicht enthalten — benutze die Schaltfläche "Template-Teile reparieren", um diese separat zu prüfen.','✅ Template fixed'=>'✅ Template repariert','✓ All parts created.'=>'✓ Alle Teile erstellt.','✓ All templates created.'=>'✓ Alle Vorlagen erstellt.','✓ All translated.'=>'✓ Alle übersetzt.','✓ Configured'=>'✓ Konfiguriert','✓ Connection OK'=>'✓ Verbindung OK','✓ Content generated — see the overlay to review, refine, and apply.'=>'✓ Inhalt erstellt — siehe die Überlagerung, um zu überprüfen, zu verfeinern und anzuwenden.','✓ Done'=>'✓ Fertig','✓ Enabled'=>'✓ Aktiviert','✓ Good length'=>'✓ Gutes Format','✓ In safe storage'=>'✓ Im sicheren Speicher','✓ Language installed.'=>'✓ Sprache installiert.','✓ Links fixed.'=>'✓ Links repariert.','✓ Nav refs fixed.'=>'✓ Navigationsreferenzen repariert.','✓ Parts fixed.'=>'✓ Teile repariert.','✓ Pattern translated.'=>'✓ Muster übersetzt.','✓ Refined — review the updated draft above.'=>'✓ Verfeinert — überprüfe den aktualisierten Entwurf oben.','✓ Translation saved'=>'✓ Übersetzung gespeichert','✗ Disabled'=>'✗ Deaktiviert','✗ Error:'=>'✗ Fehler:','✗ Failed:'=>'✗ Fehler: ','✗ Not configured'=>'✗ Nicht konfiguriert','✗ Too long'=>'✗ Zu lang','✗ Too short'=>'✗ Zu kurz','❌ Failed'=>'❌ Fehlgeschlagen','📄 Wrong template'=>'📄 Falsches Template','📍 Stale path (page moved)'=>'📍 Veralteter Pfad (Seite verschoben)']];
